import{_ as t,o as e,c as o,a2 as l}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"🎚️ 画质菜单与批量下载画质说明","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/quality-auto-downgrade.md","filePath":"troubleshooting/quality-auto-downgrade.md","lastUpdated":1784342610000}'),i={name:"troubleshooting/quality-auto-downgrade.md"};function r(n,a,s,u,d,h){return e(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="🎚️-画质菜单与批量下载画质说明" tabindex="-1">🎚️ 画质菜单与批量下载画质说明 <a class="header-anchor" href="#🎚️-画质菜单与批量下载画质说明" aria-label="Permalink to &quot;🎚️ 画质菜单与批量下载画质说明&quot;">​</a></h1><h2 id="🔍-现象" tabindex="-1">🔍 现象 <a class="header-anchor" href="#🔍-现象" aria-label="Permalink to &quot;🔍 现象&quot;">​</a></h2><ul><li>解析收藏夹 / 合集时，列表不再一条条增长，而是一次性全部出现；</li><li>画质菜单总是显示完整档位（最高到 8K），即使视频本身不支持这么高的画质；</li><li>同一批一起「下载所选」的视频，都会使用同一份下载选项（同一个画质、音质、格式）。</li></ul><h2 id="💡-原因" tabindex="-1">💡 原因 <a class="header-anchor" href="#💡-原因" aria-label="Permalink to &quot;💡 原因&quot;">​</a></h2><p>新版（yutto serve 架构）中，「解析」只获取每个视频的稳定信息：标题、封面、分 P 列表等， <strong>不再逐个请求视频的流信息</strong>。流信息接口是最容易触发 B 站风控（-412）、也最耗时的接口 —— 以一个 50 个视频的收藏夹为例，旧版（2.1.0）解析要额外发 50 次这样的请求，列表才会一条条慢慢出现。</p><p>因此现在：</p><ul><li>解析非常快，列表一次性全部出现；</li><li>解析阶段拿不到每个视频真实支持的画质，画质菜单只能显示完整档位；</li><li>真实画质在<strong>下载时</strong>才确定：以你选择的画质为上限，自动降级到该视频支持的最高画质。 所以放心选 8K —— 视频不支持时会自动回落，不会下载失败。</li></ul><div class="tip custom-block"><p class="custom-block-title">画质仍受登录状态限制</p><p>未登录最高只有 480P，1080P 以上需要登录，4K / HDR / 杜比需要大会员。 详见 <a href="/troubleshooting/low-quality-360p.html">画质只有 360P</a>。</p></div><h2 id="✅-想给不同视频用不同画质" tabindex="-1">✅ 想给不同视频用不同画质？ <a class="header-anchor" href="#✅-想给不同视频用不同画质" aria-label="Permalink to &quot;✅ 想给不同视频用不同画质？&quot;">​</a></h2><p>当前下载选项对同一批视频统一生效。想区分画质，可以分批下载： 先勾选一批、设置画质、点「下载所选」；再勾选另一批、换个画质、再下载。</p><h2 id="📮-需要逐视频画质配置" tabindex="-1">📮 需要逐视频画质配置？ <a class="header-anchor" href="#📮-需要逐视频画质配置" aria-label="Permalink to &quot;📮 需要逐视频画质配置？&quot;">​</a></h2><p>如果你的场景确实需要为每个视频单独配置画质，欢迎联系我，说说你的使用场景：</p><ul><li>💬 <a href="/guide/communication.html">联系我们（QQ 群 / B 站）</a></li><li>🐛 <a href="https://github.com/XnneHangLab/yutto-uiya/issues" target="_blank" rel="noreferrer">提交 GitHub Issue</a></li></ul>',13)])])}const _=t(i,[["render",r]]);export{p as __pageData,_ as default};
